'use strict';

const fs = require('fs');
const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);

const n = input[0];
const graph = Array.from({ length: n + 1 }, () => []);
let index = 1;

for (let i = 0; i < n - 1; i++) {
  const a = input[index++];
  const b = input[index++];
  graph[a].push(b);
  graph[b].push(a);
}

const parent = new Int32Array(n + 1);
const order = [1];
parent[1] = -1;

for (let i = 0; i < order.length; i++) {
  const node = order[i];
  for (const next of graph[node]) {
    if (next !== parent[node]) {
      parent[next] = node;
      order.push(next);
    }
  }
}

const subtreeSize = new Int32Array(n + 1);
subtreeSize.fill(1);

let answer = n;

for (let i = order.length - 1; i > 0; i--) {
  const node = order[i];
  const size = subtreeSize[node];
  answer = Math.min(answer, Math.abs(n - 2 * size));
  subtreeSize[parent[node]] += size;
}

console.log(answer.toString());
